import type { Pipeline } from '../../../schema/pipeline'

/**
 * A deal funnel from GET /Deals@Pipelines ("Query the deals funnels."),
 * requested with `$expand=Stages`. Field names are the documented ones
 * (https://developers.ploomes.com/json/openapi.json):
 *
 *   Id    "Deal funnel id, automatically generated by the database."
 *   Name  "Deal funnel name."
 *
 * and each expanded stage carries the /Deals@Stages fields:
 *
 *   Id          "Deal Stage Id, automatically generated by the Database."
 *   Name        "Deal Stage Name."
 *   PipelineId  "Deal stage funnel."
 *   Ordination  "This is the number that defines the order between the stages
 *                within a funnel, going from the smallest to the largest."
 */
export interface RawPloomesStage {
  Id: number
  Name: string
  PipelineId?: number
  Ordination: number
  [key: string]: unknown
}

export interface RawPloomesPipeline {
  Id: number
  Name: string
  Stages?: RawPloomesStage[]
  [key: string]: unknown
}

export function transformPipeline(raw: RawPloomesPipeline): Pipeline {
  // Ordination is an ordering key, not a 0-based position: sort by it and
  // number the stages from 0, which is what the canonical `order` means.
  const stages = [...(raw.Stages ?? [])].sort((a, b) => a.Ordination - b.Ordination)
  return {
    id: String(raw.Id),
    name: raw.Name,
    stages: stages.map((s, i) => ({ id: String(s.Id), name: s.Name, order: i })),
    metadata: raw,
  }
}
